# shellcheck shell=bash
# Package out/<target>/ into out/tdlib-<target>.tar.zst:
#   lib/libtdjson.a                      single prelinked object
#   include/td/telegram/td_json_client.h
#   include/td/telegram/td_log.h
#   include/td/telegram/tdjson_export.h  (generated by td's CMake)
#   tdlib.properties                     versions + linker options for cinterop

td_version() {
  sed -nE 's/^project\(TDLib VERSION ([0-9.]+).*/\1/p' "$TD_DIR/CMakeLists.txt"
}

# Extra flags the consumer must add to the cinterop .def `linkerOpts`, on top
# of what Kotlin/Native already links for the target.
target_linker_opts() {
  case "$FAMILY" in
    apple|linux) echo "" ;;   # libSystem / glibc + libstdc++ already linked by K/N
    mingw) echo "-lws2_32 -lmswsock -lnormaliz -lpsapi -lcrypt32" ;;   # as td's CMake
  esac
}

package() {
  banner "Package — $TARGET"
  local inc="$OUT_DIR/include/td/telegram"
  mkdir -p "$inc"
  cp "$TD_DIR/td/telegram/td_json_client.h" "$TD_DIR/td/telegram/td_log.h" "$inc/"
  # The generated header assumes a DLL (dllimport on Windows) unless
  # TDJSON_STATIC_DEFINE is set; this archive is always static, so bake it in
  # rather than make every consumer pass -DTDJSON_STATIC_DEFINE to cinterop.
  { printf '#ifndef TDJSON_STATIC_DEFINE\n#define TDJSON_STATIC_DEFINE\n#endif\n'
    cat "$BUILD_ROOT/td/td/telegram/tdjson_export.h"; } > "$inc/tdjson_export.h"

  cat > "$OUT_DIR/tdlib.properties" <<EOF
target=$TARGET
tdlib.version=$(td_version)
tdlib.commit=$(git -C "$TD_DIR" rev-parse HEAD)
openssl.version=$OPENSSL_VERSION
zlib.version=$ZLIB_VERSION
headers=td/telegram/td_json_client.h td/telegram/td_log.h
staticLibraries=libtdjson.a
linkerOpts=$(target_linker_opts)
EOF

  local archive="$PROJECT_ROOT/out/tdlib-$TARGET.tar.zst"
  tar -C "$OUT_DIR" -cf - . | zstd -19 -T0 -q -f -o "$archive"
  success "$(basename "$archive"): $(du -h "$archive" | cut -f1)"
}
